    _params = {}
    _params.update(_caller_params)
    raw = _get(
        f"https://pleagueofficial.com/player/{player_page_id}",
        params=_params,
        **kwargs,
    )
    if return_parsed:
        return parse_pleague_player(raw, return_as_pandas=return_as_pandas, columns=_PARSER_COLUMNS["player"])
    return raw


